public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Start and end coordinates must have two elements each.");
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    boolean[][] grid = new boolean[n][n];
    for (int[] path : paths) {
        if (path.length != 4) {
            throw new IllegalArgumentException("Each path must have four elements.");
        }
        int x1 = path[0];
        int y1 = path[1];
        int x2 = path[2];
        int y2 = path[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            throw new IllegalArgumentException("Path coordinates must be within the grid bounds.");
        }
        grid[y1][x1] = true;
        grid[y2][x2] = true;
    }

    boolean[][] visited = new boolean[n][n];
    boolean[] canReachEnd = new boolean[1];
    canReachEnd[0] = false;

    dfs(grid, startX, startY, endX, endY, visited, canReachEnd);

    return canReachEnd[0] ? "can be travelled" : "cannot be travelled";
}

private static void dfs(boolean[][] grid, int x, int y, int endX, int endY, boolean[][] visited, boolean[] canReachEnd) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[y][x] == false || visited[y][x]) {
        return;
    }

    if (x == endX && y == endY) {
        canReachEnd[0] = true;
        return;
    }

    visited[y][x] = true;

    dfs(grid, x + 1, y, endX, endY, visited, canReachEnd);
    dfs(grid, x - 1, y, endX, endY, visited, canReachEnd);
    dfs(grid, x, y + 1, endX, endY, visited, canReachEnd);
    dfs(grid, x, y - 1, endX, endY, visited, canReachEnd);
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Both words must be non-null");
    }

    word1 = word1.toLowerCase();
    word2 = word2.toLowerCase();

    Set<Character> chars1 = new HashSet<>();
    for (char c : word1.toCharArray()) {
        chars1.add(c);
    }

    int commonCount = 0;
    for (char c : word2.toCharArray()) {
        if (chars1.contains(c)) {
            commonCount++;
            chars1.remove(c);
        }
    }

    int numerator = commonCount;
    int denominator = word1.length() + word2.length() - commonCount;

    int gcd = gcd(numerator, denominator);
    return "appx(" + word1.toUpperCase() + ", " + word2.toUpperCase() + ") = " + (numerator / gcd) + "/" + (denominator / gcd);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

