public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // If the length of the array is 1, it's impossible to split it into two non-empty arrays
    if (n == 1) {
        return false;
    }

    // Iterate over possible sizes of the first part
    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            if (hasSubarrayWithSum(nums, i, sum * i / n)) {
                return true;
            }
        }
    }

    return false;
}

private boolean hasSubarrayWithSum(int[] nums, int length, int target) {
