        } else {
            char last = stack.charAt(stack.length() - 1);
            if (Character.isUpperCase(c) && Character.toLowerCase(c) == last) {
                stack.deleteCharAt(stack.length() - 1);
            } else if (Character.isLowerCase(c) && Character.toUpperCase(c) == last) {
