public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    if (low > high) {
        return steppingNumbers;
    }

    LinkedList<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num < low) continue;
        if (num > high) break;
        steppingNumbers.add(num);

        int lastDigit = num % 10;
        if (lastDigit > 0) {
            queue.offer(num * 10 + (lastDigit - 1));
        }
        if (lastDigit < 9) {
            queue.offer(num * 10 + (lastDigit + 1));
        }
    }

    return steppingNumbers;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    long factor = 1;

    while (factor <= n) {
        long lowerNumbers = n - (n / (10 * factor)) * (10 * factor);
        long currentDigit = (n / factor) % 10;
        long higherNumbers = n / (10 * factor);

        if (currentDigit == 0) {
            count += higherNumbers * factor;
        } else if (currentDigit == 1) {
            count += higherNumbers * factor + lowerNumbers + 1;
        } else {
            count += (higherNumbers + 1) * factor;
        }

        factor *= 10;
    }

    return count;
}

