public static int squarePermutations(int[] A) {
    if (A == null || A.length <= 1) {
        return 0;
    }

    boolean[][] dp = new boolean[A.length][A.length];
    for (int i = 0; i < A.length; i++) {
        dp[i][i] = true;
    }

    for (int len = 2; len <= A.length; len++) {
        for (int i = 0; i <= A.length - len; i++) {
            int j = i + len - 1;
            for (int k = i; k < j; k++) {
                if (dp[i][k] && dp[k + 1][j] && isPerfectSquare(A[i] + A[j])) {
                    dp[i][j] = true;
                    break;
                }
            }
        }
    }

    int[] dpCount = new int[1];
    dfs(A, 0, 1, dp, dpCount, new boolean[A.length]);

    return dpCount[0];
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

private static void dfs(int[] A, int index, int count, boolean[][] dp, int[] dpCount, boolean[] used) {
    if (index == A.length) {
        dpCount[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i] || (index > 0 && !dp[index - 1][i])) {
            continue;
        }
        used[i] = true;
        dfs(A, index + 1, count, dp, dpCount, used);
        used[i] = false;
    }
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;
    int i = 0;

    while (i < heights.length) {
        if (stack.isEmpty() || heights[i] >= heights[stack.peek()]) {
            stack.push(i);
            i++;
        } else {
            int topOfStack = stack.pop();
            int area = heights[topOfStack] * (stack.isEmpty() ? i : i - stack.peek() - 1);
            maxArea = Math.max(maxArea, area);
        }
    }

    while (!stack.isEmpty()) {
        int topOfStack = stack.pop();
        int area = heights[topOfStack] * (stack.isEmpty() ? i : i - stack.peek() - 1);
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Going up
            int r = Math.min(d, rows - 1);
            int c = d - r;
            while (r >= 0 && c < cols) {
                result[index++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // Going down
            int c = Math.min(d, cols - 1);
            int r = d - c;
            while (r < rows && c >= 0) {
                result[index++] = mat[r][c];
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            for (int j = digits.length - 1; j > i; j--) {
                if (digits[j] > digits[i]) {
                    char temp = digits[i];
                    digits[i] = digits[j];
                    digits[j] = temp;
                    Arrays.sort(digits, i + 1, digits.length);
                    return Integer.parseInt(new String(digits));
                }
            }
        }
    }
    return -1;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 0) return result;
    centerSymmetricNumbersHelper(n, result, new StringBuilder());
    return result;
}

private static void centerSymmetricNumbersHelper(int n, List<String> result, StringBuilder sb) {
    int len = sb.length();
    if (len == n) {
        if (len == 0 || (len == 1 && sb.charAt(0) != '0')) result.add(sb.toString());
        return;
    }
    for (char sym : new char[]{'0', '1', '6', '8', '9'}) {
        sb.append(sym);
        if (sym == '6') sb.append('9');
        else if (sym == '9') sb.append('6');
        centerSymmetricNumbersHelper(n, result, sb);
        sb.setLength(len);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    if (points[0] == null || points[1] == null || points[2] == null) {
        return false;
    }
    if (points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        return false;
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the points
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;
    int nextUglyNumber = 1;

    for (int i = 1; i < n; i++) {
        nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            i2++;
            nextMultipleOf2 = uglyNumbers[i2] * 2;
        }
        if (nextUglyNumber == nextMultipleOf3) {
            i3++;
            nextMultipleOf3 = uglyNumbers[i3] * 3;
        }
        if (nextUglyNumber == nextMultipleOf5) {
            i5++;
            nextMultipleOf5 = uglyNumbers[i5] * 5;
        }
    }

    return nextUglyNumber;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy);

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        if (next > n) {
            return;
        }
        dfs(next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    int sum = 0;
    Set<Integer> uniqueElements = new HashSet<>();

    for (int num : nums) {
        if (!uniqueElements.contains(num)) {
            uniqueElements.add(num);
            sum += num;
        }
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Worst case: 1 + 1 + ... + 1
    }

    for (int i = 1; i * i <= n; i++) {
        for (int j = i * i; j <= n; j++) {
            dp[j] = Math.min(dp[j], dp[j - i * i] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word).reverse();
        result.append(reversedWord).append(" ");
    }
    if (result.length() > 0) {
        result.setLength(result.length() - 1);
    }
    return result.toString();
}
